-- True story vs generic authored exercise: 3 source-grounded lesson corrections from Palestinian government textbooks.
-- Current Ministry portal-linked edition printed 2020. Do not claim 2026-27 reissue verified.
-- Protected append/prefix: preserves legacy original pedagogical prose without confusing it for book text.
-- No change to lesson ID, questions, activities or student history.
BEGIN;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='120s';
CREATE TEMP TABLE real_story_fix(
 lesson_id uuid PRIMARY KEY,title text NOT NULL,grade int NOT NULL,expected_unit uuid NOT NULL,
 previous_chars int NOT NULL,book_page int NOT NULL,book_url text NOT NULL,
 corrected_subject text NOT NULL,corrected_objectives jsonb NOT NULL
) ON COMMIT DROP;
INSERT INTO real_story_fix VALUES
('e2ccde53-21d3-4374-b62e-24ff66618ed1'::uuid,'الحرية أجمل',2,'cd3a849d-db92-4c7c-8288-91a5a129f676'::uuid,1362,5,'https://elearn.azureedge.net/Books/c2/ar2-p1.pdf',$fixed0$[ضاديوم — تصحيح أحداث موضوع الكتاب الأصلي: الحرية أجمل]
مصدر المقارنة: الجزء الأول من كتاب «لغتنا الجميلة» الفلسطيني للصف الثاني، الصفحة 5 وما بعدها؛ الرابط الحكومي https://elearn.azureedge.net/Books/c2/ar2-p1.pdf. طبعة الكتاب المطبوعة 2020 وهي مرتبطة ببوابة التعلم الفلسطينية حاليًا، لكن مراجعة إصدار 2026–2027 المستقل لم تثبت. هذا شرح بصياغة ضاديوم لا نسخ حرفي للقصة أو التدريبات.

أولًا: الشخصيات والموقف الأصلي
الشخصيات الأساسية عصفور حر وبلبل يعيش في قفص. شعر العصفور بالجوع والعطش، وطار بحثًا عن الطعام والشراب. لمح في شرفة أحد المنازل بلبلًا في قفص تحيط به أسباب الراحة والطعام والماء. ظن العصفور أن حياة البلبل أجمل، لكنه علم من جواب البلبل أن الطعام الجاهز لا يعوض فقدان القدرة على الطيران والخروج بحرية.
هذه أحداث موضوع الكتاب، وهي تختلف عن قصة ضاديوم القديمة التي تصف عصفورًا يبني عشًا؛ فلا أستخدم أحداث القصة الإثرائية للإجابة عن أسئلة «الحرية أجمل».

ثانيًا: أفهم الفكرة وأوضح الأسباب
الفكرة الرئيسة أن الحرية قيمة عظيمة، وأن وجود الطعام والأمان المادي لا يكفي وحده للحياة السعيدة حين يحرم الكائن من الحركة والاختيار. سبب حزن البلبل أنه محبوس في القفص. موقف العصفور تغير عندما عرف مشاعر البلبل. أفرّق بين حالة طائر حر يبحث عن طعامه وحالة طائر يتوافر له طعام لكنه لا يستطيع الخروج.

ثالثًا: أتعلم مفردات الكتاب في سياقها
«القفص» مكان ذو قضبان يُحبس فيه الطائر؛ «البلبل» نوع من الطيور؛ «الشرفة» جزء بارز من المنزل؛ «مسجون» محروم من الحرية؛ «العطش» الحاجة إلى الماء. أضع المفردة في جملة جديدة من عندي: «يريد الطائر أن يطير بحرية». لا أفترض أن العصفور نفسه كان في القفص؛ فالمحبوس هو البلبل.

رابعًا: مهارات اللغة من صفحات الدرس
أتعرف حرف الباء في «بلبل» و«بعيد» وأحدد موضعه، وأميز حرف التاء في كلمة «تعب» والثاء في «كثير». أراجع المد بالألف في كلمة مثل «باب»، والمد بالواو في «نور»، والمد بالياء في «جميل»، مع النطق الصحيح. أحلل الجملة إلى كلمات ثم أكون جملة من إنشائي: «الحرية قيمة جميلة». يراجع المعلم الخط واتجاه الكتابة والتشكيل بما يلائم الصف الثاني.

خامسًا: تقويم فهم موضوع الدرس
لماذا بحث العصفور عن الطعام؟ أين كان البلبل؟ لماذا لم يكن راضيًا عن حياته؟ ماذا تعلّم العصفور من رده؟ أجيب بأدلة مأخوذة من الأحداث المذكورة. أكتب جملتين عن أهمية الحرية وحسن رعاية الكائنات، وأميّز بين رأيي والحدث الذي ورد في النص.
[نهاية التصحيح المبني على نص الكتاب الحقيقي]$fixed0$,'["أن يرتب الطالب ثلاثة أحداث صحيحة في درس «الحرية أجمل» ويحدد العصفور والبلبل.","أن يشرح الطالب سبب حزن البلبل ويستشهد بحدث من النص ثم يفسر مفردتين.","أن يحدد الطالب حرف الباء والمد بالألف في كلمتين ويكتب جملة عن الحرية دون خلط بالقصة الإثرائية."]'::jsonb),
('0ff35b05-a4cb-4c0d-907d-f17d75b40b78'::uuid,'الرسامة الصغيرة',2,'cd3a849d-db92-4c7c-8288-91a5a129f676'::uuid,1423,15,'https://elearn.azureedge.net/Books/c2/ar2-p1.pdf',$fixed1$[ضاديوم — تصحيح أحداث موضوع الكتاب الأصلي: الرسامة الصغيرة]
مصدر المقارنة: الجزء الأول من الكتاب الفلسطيني «لغتنا الجميلة» للصف الثاني، الصفحة 15 وما بعدها؛ https://elearn.azureedge.net/Books/c2/ar2-p1.pdf. الطبعة المطبوعة 2020، المرتبطة بالبوابة الفلسطينية حاليًا؛ لا تُعد شهادة مطابقة لطبعة 2026–2027 غير المفحوصة. النص أدناه شرح مستقل للأحداث والمفاهيم، لا نقل للقصة الأصلية.

أولًا: أتعرف الشخصية والمكان
الرسامة الصغيرة في الكتاب هي «خلود»، وليست «ريم» الواردة في القصة الإثرائية القديمة لضاديوم. كانت خلود ترسم علمًا على رمل الشاطئ، لكن موج البحر كان يمحو رسمها. شاهدتها أمها وقدرت اهتمامها بالرسم، فأحضرت لها دفترًا وألوانًا. بدأت خلود ترسم ما تراه داخل دفترها حتى جمعت لوحات متعددة. لاحظت معلمتها جمال رسومها عندما شاهدتها في المدرسة وأثنت على موهبتها.

ثانيًا: أرتب التحول في القصة
البداية: محاولة الرسم على الرمل قرب البحر. المشكلة: الموج يمحو الرسوم مرارًا. المساعدة: الأم توفر دفتر الرسم والألوان. النتيجة: أصبح لخلود مكان تحتفظ فيه برسومها وتواصل التدريب. رد فعل المعلمة: تشجيع خلود والثناء على عملها. ألاحظ أن التشجيع والأدوات المناسبة والمثابرة تساعد على نمو الموهبة.

ثالثًا: أفسر الكلمات وأميز المعنى
«الشاطئ» أرض بجوار البحر؛ «الموج» حركة الماء في البحر؛ «دفتر الرسم» صفحات تحفظ فيها الرسومات؛ «الألوان» أدوات لتلوين اللوحة؛ «الموهبة» استعداد ينمو بالتعلم والممارسة؛ «لوحة» رسم أبدعه شخص. أعبر بجملة جديدة: «تتدرب خلود على الرسم في دفترها»، ثم أشرح لماذا كان الدفتر أنسب من الرمل لحفظ الرسم.

رابعًا: أتعلم من الموضوع لا من العنوان
أصف مكان الحدث الأول وهو الشاطئ، ثم المكان الذي شاهَدت فيه المعلمة الرسوم وهو المدرسة. أميز بين سبب المشكلة وأثرها: الموج سبب ضياع الرسم، وشراء الدفتر ساعد على حفظه. أستعمل أدوات الترتيب «أولًا، ثم، بعد ذلك، أخيرًا» لبناء فقرة من أربع جمل. وأكتب جملة تشجيع مهذبة لفنان صغير مثل «واصل المحاولة وتعلم من تجربتك».

خامسًا: أسئلة دقيقة عن نص الكتاب
من الشخصية التي تحب الرسم؟ ماذا كانت ترسم على الرمل؟ ما الذي كان يمحو رسمها؟ من الذي اشترى لها أدوات الرسم؟ ماذا قالت لها المعلمة أو كيف شجعتها؟ أجيب عن الأحداث الحقيقية لخلود، لا عن قصة ريم الإثرائية القديمة. أكتب ملخصًا من ثلاثة أسطر، وأذكر كيف أساند صديقًا يتعلم مهارة جديدة.
[نهاية التصحيح المبني على نص الكتاب الحقيقي]$fixed1$,'["أن يرتب الطالب أربعة أحداث من قصة خلود في «الرسامة الصغيرة» ترتيبًا صحيحًا.","أن يفسر الطالب كيف عالجت الأسرة مشكلة ضياع الرسم ويذكر دليلاً من القصة.","أن يكتب الطالب ثلاثة أسطر عن الموهبة والتشجيع مستخدمًا أدوات ترتيب الأحداث."]'::jsonb),
('ab5f5652-d42e-4dc6-8935-17309920d1bc'::uuid,'ذهب الأرض',3,'5149edd7-6075-4840-b03b-bb8419b587e2'::uuid,937,5,'https://elearn.azureedge.net/Books/c3/ar3-p1.pdf',$fixed2$[ضاديوم — تصحيح أحداث موضوع الكتاب الأصلي: ذهب الأرض]
مصدر المقارنة: الجزء الأول من كتاب «لغتنا الجميلة» للصف الثالث الفلسطيني، الصفحة 5 وما بعدها؛ https://elearn.azureedge.net/Books/c3/ar3-p1.pdf. الطبعة المطبوعة 2020 التي ترتبط بها بوابة التعليم الفلسطينية حاليًا، ولم تُعتمد مطابقتها لأي تحديث لاحق. الشرح الآتي من صياغة ضاديوم ويبين موضوع الكتاب الحقيقي، ولا يعيد نسخ النص الوزاري.

أولًا: من الشخصيات وما المشكلة؟
القصة تدور حول أخوين اقتسما ما تركه والدهما من مال وأرض. اختار الأخ الأصغر الذهب، وأخذ الأخ الأكبر الأرض. مرّت ثلاثة أعوام، ثم عاد الأصغر وقد أنفق ما كان معه. أما الأكبر فقد عمل في أرضه وزرعها واعتنى بها، فأثمرت ونفعته. عندما جاء أخوه محتاجًا لم يتركه، بل أعطاه مالًا ودعاه إلى العمل والاستفادة من الأرض.

ثانيًا: لماذا أصبحت الأرض «ذهبًا»؟
عنوان الدرس لا يقصد أن التربة تحولت فعليًا إلى ذهب، بل هو تعبير مجازي عن قيمة الأرض المنتجة. الفرق بين الأخوين ليس مجرد امتلاك مال؛ بل في طريقة استخدام الموارد. الصغير استهلك نصيبه دون أن يحافظ عليه، والكبير استثمر الأرض بالعمل المستمر حتى صارت مصدر رزق. أعلم أن القيمة الأساسية للعمل والاعتماد على النفس مع مساعدة المحتاجين.

ثالثًا: أفهم المفردات وأستدل
«اقتسما» وزعا الشيء بينهما؛ «الثروة» مال أو ممتلكات ذات قيمة؛ «وفيرة» كثيرة؛ «مَنَح» أعطى؛ «زراعة» رعاية نباتات تنمو في الأرض. أميز بين الحقيقة والرأي: من حقائق القصة أن الأصغر اختار الذهب وأن الأكبر زرع الأرض؛ ومن الاستنتاجات أن العمل والاستمرار ينميان الموارد. أستدل على كرم الأخ الأكبر بأنه ساعد أخاه بعد عودته.

رابعًا: اللغة المرتبطة بالدرس
أميز الفعل الماضي في جملة «زرعَ الفلاحُ الأرضَ» وأقارنه بصيغته عند إسناده إلى مؤنث: «زرعتْ المزارعةُ الأرضَ». أقارن بين الاسم والفعل وأكتب جملتين جديدتين، وأتدرب على قراءة التنوين في كلمات قصيرة مثل «عملٌ» و«أرضًا» و«خيرٍ» مع مراعاة النطق. أكتب الجملة بخط النسخ واضحًا، وأراجع همزة الكلمات والتاء المربوطة.

خامسًا: أفكر وأكتب
ماذا اختار الأخ الأصغر؟ ماذا اختار الأكبر؟ لماذا كان الأكبر قادرًا على مساعدة أخيه بعد سنوات؟ ما معنى عنوان «ذهب الأرض»؟ وكيف تصرف الكبير مع المحتاج؟ أكتب فقرة من أربعة أسطر أشرح فيها الفرق بين إنفاق الموارد والاستفادة منها بالعمل. لا أستخدم قصة الرحلة المدرسية القديمة المضافة في ضاديوم بديلًا عن أحداث الأخوين المقررة.
[نهاية التصحيح المبني على نص الكتاب الحقيقي]$fixed2$,'["أن يذكر الطالب ما اختاره كل أخ عند اقتسام الميراث ويشرح ما حدث بعد ثلاثة أعوام.","أن يوضح الطالب معنى «ذهب الأرض» المجازي ويستشهد بحدث يبين قيمة الزراعة والعمل.","أن يميز الطالب الفعل الماضي في مثالين ويكتب فقرة قصيرة عن العمل والمحافظة على الموارد."]'::jsonb);
DO $pre$
DECLARE bad int;
BEGIN
 IF (SELECT count(*) FROM real_story_fix)<>3 THEN RAISE EXCEPTION 'Need 3 source stories';END IF;
 SELECT count(*) INTO bad FROM real_story_fix x
 LEFT JOIN lessons l ON l.id=x.lesson_id
 LEFT JOIN units u ON u.id=l.unit_id JOIN grades g ON g.id=u.grade_id
 LEFT JOIN curricula cu ON cu.id=g.curriculum_id JOIN countries c ON c.id=cu.country_id
 WHERE l.id IS NULL OR l.title<>x.title OR c.code<>'PS' OR g.grade_number<>x.grade
 OR cu.academic_year<>'2026-2027' OR l.unit_id<>x.expected_unit
 OR l.status<>'published' OR l.semester<>1 OR length(l.content)<>x.previous_chars
 OR l.source_pdf_url<>x.book_url OR l.source_page_start<>x.book_page
 OR l.content LIKE '%[ضاديوم — تصحيح أحداث موضوع الكتاب الأصلي:%'
 OR length(x.corrected_subject)<1800 OR jsonb_array_length(x.corrected_objectives)<>3
 OR EXISTS(SELECT 1 FROM student_lesson_progress p WHERE p.lesson_id=l.id)
 OR EXISTS(SELECT 1 FROM question_attempts qa JOIN questions q ON q.id=qa.question_id WHERE q.lesson_id=l.id)
 OR EXISTS(SELECT 1 FROM lesson_activity_attempts aa JOIN lesson_activities a ON a.id=aa.activity_id WHERE a.lesson_id=l.id);
 IF bad<>0 THEN RAISE EXCEPTION 'Rollback % mismatched/unsafe subjects',bad;END IF;
END $pre$;
UPDATE lessons l SET content=x.corrected_subject||E'\n\nــــــــــ\nنص ضاديوم الإثرائي السابق مستقل، ولا يحكي أحداث الكتاب الحكومية:\n\n'||l.content,
learning_objectives=x.corrected_objectives,updated_at=now()
FROM real_story_fix x WHERE l.id=x.lesson_id;
DO $post$
DECLARE n int;
BEGIN
 SELECT count(*) INTO n FROM real_story_fix x JOIN lessons l ON l.id=x.lesson_id
 WHERE l.content LIKE '[ضاديوم — تصحيح أحداث موضوع الكتاب الأصلي:%'
 AND l.content LIKE '%[نهاية التصحيح المبني على نص الكتاب الحقيقي]%'
 AND l.learning_objectives=x.corrected_objectives
 AND l.content LIKE '%نص ضاديوم الإثرائي السابق مستقل%';
 IF n<>3 THEN RAISE EXCEPTION 'Rollback only % of 3 corrected',n;END IF;
END $post$;
COMMIT;
